// QR-энкодер (ТЗ §6): минимальный, без зависимостей. Матрицы-снимки ниже
// сгенерированы нашим кодом и независимо проверены декодером (zxing-cpp) —
// каждый снимок гарантированно читается в исходную строку. QR нужен только
// для показа otpauth:// при настройке 2FA; рядом всегда есть секрет и URI.
import { describe, expect, it } from 'vitest';
import { encodeQr, qrDataUrl, qrToSvg } from './qr';

const URI =
  'otpauth://totp/Puls:user@example.com?secret=JBSWY3DPEHPK3PXPJBSWY3DPEHPK3PXP&issuer=Puls&algorithm=SHA1&digits=6&period=30';

const SNAPSHOTS: ReadonlyArray<{
  data: string;
  ecc: 'L' | 'M' | 'Q';
  mask?: number;
  version: number;
  size: number;
  matrix: string;
}> = [
  {
    data: 'HELLO',
    ecc: 'L',
    mask: 0,
    version: 1,
    size: 21,
    matrix:
      '',
  },
  {
    data: URI,
    ecc: 'M',
    version: 7,
    size: 45,
    matrix:
      '',
  },
  {
    data: 'AAAAAAAAAAAAAAAAAAAA',
    ecc: 'Q',
    mask: 3,
    version: 2,
    size: 25,
    matrix:
      '',
  },
];

describe('QR-энкодер', () => {
  for (const snapshot of SNAPSHOTS) {
    it(`совпадает с проверенным снимком: ${snapshot.ecc}-${snapshot.version}`, () => {
      const qr = encodeQr(snapshot.data, { errorCorrection: snapshot.ecc, mask: snapshot.mask });
      expect(qr.version).toBe(snapshot.version);
      expect(qr.size).toBe(snapshot.size);
      expect(qr.modules.map((row) => row.join('')).join('/')).toBe(snapshot.matrix);
    });
  }

  it('подбирает версию и маску сам', () => {
    expect(encodeQr('HELLO', { errorCorrection: 'L' }).version).toBe(1);
    expect(encodeQr(URI, { errorCorrection: 'M' }).version).toBe(7);
    const auto = encodeQr(URI, { errorCorrection: 'M' }).mask;
    expect(auto).toBeGreaterThanOrEqual(0);
    expect(auto).toBeLessThanOrEqual(7);
  });

  it('рисует обязательные структурные элементы', () => {
    const qr = encodeQr(URI, { errorCorrection: 'M' });
    const modules = qr.modules;
    const size = qr.size;

    // «Глаза» в трёх углах: 7×7 плюс разделители.
    for (const [top, left] of [
      [0, 0],
      [0, size - 7],
      [size - 7, 0],
    ]) {
      expect(modules[top][left]).toBe(1);
      expect(modules[top + 6][left + 6]).toBe(1);
      expect(modules[top + 1][left + 1]).toBe(0);
    }
    // Тайминг-паттерн: чередование по строке и столбцу 6.
    for (let i = 8; i < size - 8; i += 1) {
      expect(modules[6][i]).toBe(modules[i][6]);
    }
  });

  it('формат-биты кодируют уровень коррекции и маску', () => {
    const qr = encodeQr('HELLO', { errorCorrection: 'L', mask: 3 });
    // Первая копия формат-инфо: биты 0..5 — столбец 8, биты 6..8, затем строка 8.
    const bit = (i: number): number => {
      if (i <= 5) return qr.modules[i][8];
      if (i === 6) return qr.modules[7][8];
      if (i === 7) return qr.modules[8][8];
      if (i === 8) return qr.modules[8][7];
      return qr.modules[8][14 - i];
    };
    let value = 0;
    for (let i = 0; i < 15; i += 1) value |= bit(i) << i;
    // Пересчитываем BCH(15,5) с XOR-маской 0x5412 для L и маски 3.
    const data = (1 << 3) | 3;
    let remainder = data;
    for (let i = 0; i < 10; i += 1) remainder = (remainder << 1) ^ ((remainder >>> 9) * 0x537);
    expect(value).toBe(((data << 10) | remainder) ^ 0x5412);
  });

  it('падает на слишком длинных данных', () => {
    expect(() => encodeQr('x'.repeat(5000), { errorCorrection: 'H', maxVersion: 10 })).toThrow();
  });

  it('рисует SVG и data-URL', () => {
    const qr = encodeQr('HELLO', { errorCorrection: 'L' });
    const svg = qrToSvg(qr.modules);
    expect(svg.startsWith('<svg')).toBe(true);
    expect(svg).toContain('viewBox');

    const dataUrl = qrDataUrl('HELLO', { errorCorrection: 'L' });
    expect(dataUrl.startsWith('data:image/svg+xml;base64,')).toBe(true);
    expect(qrDataUrl(URI, { errorCorrection: 'M', margin: 2 }).length).toBeGreaterThan(100);
  });
});
